ALTER TABLE public.provider_network_profiles ADD COLUMN nearby_opt_in boolean NOT NULL DEFAULT false, ADD COLUMN matching_settings jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN matching_consent jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.trip_network_settings ADD COLUMN max_candidates integer NOT NULL DEFAULT 5 CHECK(max_candidates BETWEEN 1 AND 25), ADD COLUMN response_minutes integer NOT NULL DEFAULT 60 CHECK(response_minutes BETWEEN 5 AND 1440), ADD COLUMN max_radius integer NOT NULL DEFAULT 200 CHECK(max_radius IN (20,50,100,200));
ALTER TABLE public.provider_trip_offers ADD COLUMN match_explanation jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE FUNCTION public.save_nearby_settings(_ws uuid,_enabled boolean,_settings jsonb,_source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.network_workspace_access(_ws,true) OR NOT public.can_manage_account_connections(_ws) OR _enabled IS NULL OR _source NOT IN ('settings','onboarding') THEN RAISE EXCEPTION 'Provider manager required'; END IF;
IF coalesce(_settings->>'state','')!~'^[A-Z]{2}$' OR length(coalesce(_settings->>'publicLabel',''))>160 OR length(coalesce(_settings->>'displayName',''))>160 OR coalesce(_settings->>'availability','') NOT IN ('available','paused','unavailable') OR coalesce((_settings->>'radius')::integer,0) NOT BETWEEN 1 AND 200 OR coalesce(_settings->>'timezone','') NOT IN (SELECT name FROM pg_timezone_names) OR jsonb_typeof(_settings->'days') IS DISTINCT FROM 'array' OR jsonb_array_length(_settings->'days')>7 OR coalesce(_settings->>'start','')!~'^[0-2][0-9]:[0-5][0-9]$' OR coalesce(_settings->>'end','')!~'^[0-2][0-9]:[0-5][0-9]$' OR (_settings->>'start')::time>=(_settings->>'end')::time THEN RAISE EXCEPTION 'Complete state, radius, timezone and same-day operating hours';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(_settings->'days') d WHERE d!~'^[0-6]$') THEN RAISE EXCEPTION 'Invalid operating day'; END IF;
IF _enabled AND (jsonb_array_length(_settings->'days')=0 OR NOT EXISTS(SELECT 1 FROM public.provider_network_profiles p WHERE p.workspace_id=_ws AND cardinality(p.service_types)>0 AND (cardinality(p.zips)>0 OR cardinality(p.cities)>0 OR cardinality(p.counties)>0))) THEN RAISE EXCEPTION 'Services and explicit service geography required before nearby consent'; END IF;
UPDATE public.provider_network_profiles SET nearby_opt_in=_enabled,matching_settings=_settings,matching_consent=jsonb_build_object('version','2026-11-15','at',now(),'user',auth.uid(),'workspace',_ws,'source',_source,'enabled',_enabled),updated_by=auth.uid(),updated_at=now() WHERE workspace_id=_ws;
IF NOT FOUND THEN RAISE EXCEPTION 'Save service profile first'; END IF;
INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,details) VALUES(_ws,'nearby_consent_changed',auth.uid(),jsonb_build_object('version','2026-11-15','source',_source,'enabled',_enabled)); END $$;
REVOKE ALL ON FUNCTION public.save_nearby_settings(uuid,boolean,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_nearby_settings(uuid,boolean,jsonb,text) TO authenticated;
CREATE FUNCTION public.nearby_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF current_user NOT IN ('postgres','service_role','supabase_admin') AND (NEW.nearby_opt_in IS DISTINCT FROM OLD.nearby_opt_in OR NEW.matching_consent IS DISTINCT FROM OLD.matching_consent OR NEW.matching_settings IS DISTINCT FROM OLD.matching_settings) THEN RAISE EXCEPTION 'Use audited nearby settings';END IF;RETURN NEW;END $$;
CREATE TRIGGER nearby_profile_update_guard BEFORE UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.nearby_profile_guard();
CREATE FUNCTION public.network_matching_candidates(_distribution uuid,_radius integer) RETURNS TABLE(workspace uuid,score integer,explanation jsonb,excluded text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;p record;reasons text[];distance float8;area boolean;veh boolean;drv boolean;BEGIN
SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution;
IF NOT public.network_source_access(_distribution,true) THEN RAISE EXCEPTION 'Distribution unavailable';END IF;
FOR p IN SELECT w.id,w.status,w.provider_verified,w.provider_subtype,w.is_test_account,np.* FROM public.workspaces w JOIN public.provider_network_profiles np ON np.workspace_id=w.id WHERE w.account_type='provider' LOOP
reasons:='{}';distance:=NULL;area:=lower(d.pickup_area)=ANY(SELECT lower(x) FROM unnest(p.cities) x);
IF NOT p.nearby_opt_in THEN reasons:=array_append(reasons,'Nearby consent off');END IF;
IF p.status<>'active' OR p.is_test_account OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles up ON up.user_id=m.user_id WHERE m.workspace_id=p.id AND m.role='owner' AND m.removed_at IS NULL AND up.status='active' AND NOT up.is_test_account AND up.deleted_at IS NULL) THEN reasons:=array_append(reasons,'Inactive account');END IF;
IF NOT public.provider_network_entitled(p.id) THEN reasons:=array_append(reasons,'Membership required');END IF;
IF p.id=d.source_workspace_id THEN reasons:=array_append(reasons,'Sending account');END IF;
IF p.provider_subtype='independent_contractor' THEN
IF d.capability<>'ambulatory' OR NOT public.contractor_connected(d.source_workspace_id,p.id) OR NOT coalesce((public.contractor_evidence_summary(p.id)->>'eligible')::boolean,false) THEN reasons:=array_append(reasons,'Contractor evidence or connection required');END IF;
ELSIF NOT p.provider_verified OR p.service_base_verified_at IS NULL OR p.eligibility_expires_at IS NULL OR p.eligibility_expires_at<=now() THEN reasons:=array_append(reasons,'Current verification required');END IF;
IF NOT d.capability=ANY(p.approved_service_types) THEN reasons:=array_append(reasons,'Service not approved');END IF;
IF p.service_base_verified_at IS NOT NULL AND p.service_base_lat IS NOT NULL AND p.service_base_lng IS NOT NULL THEN distance:=public.haversine_miles(d.pickup_lat,d.pickup_lng,p.service_base_lat,p.service_base_lng);area:=area OR distance<=least(_radius,coalesce(p.service_radius_miles,0));END IF;
IF NOT area OR (distance IS NOT NULL AND distance>_radius) THEN reasons:=array_append(reasons,'Service area mismatch');END IF;
IF p.matching_settings->>'availability' IS DISTINCT FROM 'available' OR p.matching_settings->>'acceptingTrips' IS DISTINCT FROM 'true' THEN reasons:=array_append(reasons,'Unavailable');END IF;
IF coalesce(p.matching_settings->>'timezone','') NOT IN (SELECT name FROM pg_timezone_names) OR NOT coalesce(p.matching_settings->'days','[]') @> to_jsonb(ARRAY[extract(dow FROM d.pickup_date)::integer]) OR NOT (d.pickup_time>=coalesce(p.matching_settings->>'start','00:00')::time AND d.pickup_time<coalesce(p.matching_settings->>'end','00:00')::time) THEN reasons:=array_append(reasons,'Operating hours missing or outside schedule');END IF;
IF coalesce((SELECT hold FROM public.contractor_safety_events WHERE workspace_id=p.id ORDER BY created_at DESC LIMIT 1),false) THEN reasons:=array_append(reasons,'Safety hold');END IF;
IF EXISTS(SELECT 1 FROM public.network_settlements s WHERE (s.sender_workspace_id=p.id OR s.receiver_workspace_id=p.id) AND (s.dispute_opened_at IS NOT NULL AND s.dispute_resolved_at IS NULL OR s.sender_workspace_id=p.id AND s.payment_deadline_at<now() AND s.payment_succeeded_at IS NULL)) THEN reasons:=array_append(reasons,'Payment or dispute hold');END IF;
veh:=EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=p.id AND v.status='active' AND v.operation_type='human_driven' AND v.capacity>0 AND (d.capability=ANY(v.service_capabilities) OR d.capability='ambulatory' AND v.vehicle_type IN ('sedan','suv','van')) AND (d.capability<>'wheelchair' OR v.wheelchair_capacity>0) AND NOT EXISTS(SELECT 1 FROM public.trips t WHERE t.vehicle_id=v.id AND t.pickup_date=d.pickup_date AND t.status NOT IN ('completed','canceled','cancelled') AND (t.pickup_time=d.pickup_time OR t.estimated_duration_seconds IS NULL OR t.estimated_duration_seconds<=0 OR d.pickup_time BETWEEN t.pickup_time AND t.pickup_time+make_interval(secs=>t.estimated_duration_seconds))));
drv:=p.provider_subtype='independent_contractor' AND coalesce((public.contractor_evidence_summary(p.id)->>'eligible')::boolean,false) OR EXISTS(SELECT 1 FROM public.drivers v WHERE v.workspace_id=p.id AND v.status='active' AND v.license_expiry>=d.pickup_date AND d.capability=ANY(v.service_capabilities) AND NOT (d.pickup_date BETWEEN coalesce(v.vacation_start,'infinity'::date) AND coalesce(v.vacation_end,'infinity'::date)) AND NOT EXISTS(SELECT 1 FROM public.trips t WHERE t.driver_id=v.id AND t.pickup_date=d.pickup_date AND t.status NOT IN ('completed','canceled','cancelled') AND (t.pickup_time=d.pickup_time OR t.estimated_duration_seconds IS NULL OR t.estimated_duration_seconds<=0 OR d.pickup_time BETWEEN t.pickup_time AND t.pickup_time+make_interval(secs=>t.estimated_duration_seconds))));
IF NOT veh THEN reasons:=array_append(reasons,'Eligible vehicle required');END IF;IF NOT drv THEN reasons:=array_append(reasons,'Eligible driver required');END IF;
IF EXISTS(SELECT 1 FROM public.provider_trip_offers o WHERE o.distribution_id=d.id AND o.provider_workspace_id=p.id) THEN reasons:=array_append(reasons,'Already offered');END IF;
workspace:=p.id;excluded:=array_to_string(reasons,'; ');score:=CASE WHEN cardinality(reasons)>0 THEN 0 ELSE (CASE WHEN lower(d.pickup_area)=ANY(SELECT lower(x) FROM unnest(p.cities) x) THEN 70 ELSE 20 END)+30+CASE WHEN distance IS NULL THEN 0 ELSE greatest(0,20-floor(distance/10)::integer) END END;explanation:=jsonb_build_array('Service area match','Eligible vehicle and driver','Operating during requested time')||CASE WHEN distance IS NULL THEN '[]'::jsonb ELSE jsonb_build_array('Approximately '||round(distance)::text||' miles from pickup') END;RETURN NEXT;
END LOOP;END $$;
REVOKE ALL ON FUNCTION public.network_matching_candidates(uuid,integer) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.network_preview_matching(_distribution uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE radius integer;res jsonb;BEGIN
IF NOT public.network_source_access(_distribution,true) THEN RAISE EXCEPTION 'Distribution unavailable';END IF;
SELECT CASE coalesce(current_radius,0) WHEN 0 THEN 20 WHEN 20 THEN 50 WHEN 50 THEN 100 WHEN 100 THEN 200 ELSE 200 END INTO radius FROM public.trip_distributions WHERE id=_distribution;
SELECT jsonb_build_object('radius',radius,'eligible',count(*) FILTER(WHERE excluded=''),'excluded',coalesce((SELECT jsonb_object_agg(reason,n) FROM (SELECT reason,count(*) n FROM public.network_matching_candidates(_distribution,radius) c CROSS JOIN LATERAL unnest(string_to_array(c.excluded,'; ')) reason WHERE reason<>'' GROUP BY reason) x),'{}'::jsonb),'enabled',EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='nearby_matching' AND enabled),'candidates',CASE WHEN public.has_role(auth.uid(),'admin') THEN coalesce(jsonb_agg(jsonb_build_object('workspace',workspace,'score',score,'explanation',explanation) ORDER BY score DESC,workspace) FILTER(WHERE excluded=''),'[]'::jsonb) ELSE '[]'::jsonb END) INTO res FROM public.network_matching_candidates(_distribution,radius);RETURN res;END $$;
REVOKE ALL ON FUNCTION public.network_preview_matching(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.network_preview_matching(uuid) TO authenticated;